solution.jsx:
function Panel({ title, actions, children }) {
  return (
    <section>
      <header>
        <h2>{title}</h2>
        {actions}
      </header>
      <div>{children}</div>
    </section>
  );
}

export default function App() {
  return (
    <main>
      <Panel title="To watch" actions={<button>Shuffle</button>}>
        <ul>
          <li>Past Lives</li>
          <li>Paddington 2</li>
        </ul>
      </Panel>
      <Panel title="Watched">
        <p>You've watched 1 movie.</p>
      </Panel>
    </main>
  );
}
